// Después de los 45s de espera, chequeamos si el pendiente sigue 'pendiente'.
// Si otro flow (texto) lo procesó, ya no preguntamos.
const resp = $input.first().json;
const rows = resp.values || [];
const dataRows = rows.slice(1);

// El messageId del pago original viaja en el item — lo recuperamos.
// Como en este punto el item viene del Read (sin nuestros datos), usamos $('Construir Pendiente') para traerlos.
const origData = $('Construir Pendiente').first().json;
const messageId = origData.messageId;

let pendienteActivo = null;
for (const r of dataRows) {
  if (r[0] === messageId && r[13] === 'pendiente') {
    pendienteActivo = true;
    break;
  }
}

return [{ json: { ...origData, sigueActivo: !!pendienteActivo } }];

