// Clasifica el texto: si es un comando 'PAGO X CLIENTE [cta N]' lo parseamos
// directo acá y lo mandamos por el flujo de carga. Si no, va por el flujo
// de respuesta a un Pendiente.
const configItem = $('Config').first().json;
const config = configItem.config;
const original = configItem.original;
const aliases = config.clientAliases;

const userText = original.data.message?.conversation
  || original.data.message?.extendedTextMessage?.text
  || '';

// Sacar @mención al bot del principio si hay
const cleaned = userText.trim().replace(/^@\S+\s*/i, '').trim();

// Match: PAGO <monto>[K|M] <cliente> [cta 1|2]
// Ej: 'pago 500K farias', 'PAGO $500.000 ROCAS RAMIRO cta 1', 'pago 1.5m cinna'
const pagoMatch = cleaned.match(/^pago\s+\$?([\d.,]+)\s*([kKmM]?)\s+(.+?)(?:\s+cta\s*([12]))?\s*$/i);

function normalize(s) {
  return (s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9 ]/g, '').trim();
}

const baseData = {
  config,
  groupJid: config.groupJid,
  senderJid: original.data.key.participant || original.data.key.remoteJid,
  messageId: original.data.key.id,
  userText
};

if (!pagoMatch) {
  return [{ json: { ...baseData, tipoMensaje: 'reply' } }];
}

const numStr = pagoMatch[1].replace(/[.,]/g, '');
let monto = parseInt(numStr, 10);
if (!monto) return [{ json: { ...baseData, tipoMensaje: 'reply' } }];

const mult = (pagoMatch[2] || '').toLowerCase();
if (mult === 'k') monto *= 1000;
if (mult === 'm') monto *= 1000000;

const clienteTexto = pagoMatch[3].trim();
const cuentaTexto = pagoMatch[4];
const cuenta = cuentaTexto ? parseInt(cuentaTexto, 10) : 1;

let sheetName = null;
const clienteNorm = normalize(clienteTexto);
for (const [alias, sheet] of Object.entries(aliases)) {
  const aliasNorm = normalize(alias);
  if (clienteNorm.includes(aliasNorm) || aliasNorm.includes(clienteNorm)) {
    sheetName = sheet;
    break;
  }
}

// Quiso hacer un PAGO pero no reconocemos al cliente — avisamos en lugar de ignorar
if (!sheetName) {
  return [{
    json: {
      ...baseData,
      tipoMensaje: 'pago_no_match',
      clienteTexto,
      monto
    }
  }];
}

return [{
  json: {
    ...baseData,
    tipoMensaje: 'pago_manual',
    extracted: {
      tipo: 'pago_efectivo',
      monto,
      numero_comprobante: '',
      nota_corta: 'efectivo',
      cliente_detectado: clienteTexto,
      fecha: ''
    },
    sheetName,
    cuenta,
    esRemito: false,
    esNDC: false,
    esTransferencia: true,
    esCheque: false,
    esEcheq: false,
    esPago: true
  }
}];

