// Busca el último pendiente activo del grupo
const resp = $input.first().json;
const rows = resp.values || [];
const dataRows = rows.slice(1);

const configItem = $('Config').first().json;
const config = configItem.config;
const original = configItem.original;
const groupJid = config.groupJid;

let pendiente = null;
let pendienteRowIndex = -1;
let latestTs = 0;

for (let i = 0; i < dataRows.length; i++) {
  const r = dataRows[i];
  if (r[13] === 'pendiente' && r[15] === groupJid) {
    const ts = new Date(r[1]).getTime();
    if (ts > latestTs) {
      latestTs = ts;
      pendiente = {
        id: r[0],
        timestamp: r[1],
        tipo: r[2],
        cliente_detectado: r[3],
        sheet_name: r[4],
        cuenta: r[5] ? parseInt(r[5]) : null,
        monto: r[6] ? parseFloat(r[6]) : null,
        comprobante: r[7],
        fecha: r[8],
        nota: r[9],
        banco: r[10],
        dueno_cheque: r[11],
        fecha_cobro: r[12],
        status: r[13],
        razon: r[14],
        chat_jid: r[15]
      };
      pendienteRowIndex = i + 2;
    }
  }
}

const userText = original.data.message?.conversation
  || original.data.message?.extendedTextMessage?.text
  || '';

return [{
  json: {
    pendiente,
    pendienteRowIndex,
    userText,
    config,
    groupJid,
    senderJid: original.data.key.participant || original.data.key.remoteJid
  }
}];

