// Parsea la respuesta de Claude y arma la estructura para Preparar fila si es cargar.
const claudeResp = $input.first().json;
const rawText = claudeResp.content?.[0]?.text || '{}';

let decision;
try {
  const cleaned = rawText.replace(/^```json\s*/i, '').replace(/```\s*$/, '').trim();
  decision = JSON.parse(cleaned);
} catch (e) {
  decision = { accion: 'ignorar', razon: 'No se pudo parsear: ' + rawText.slice(0, 100) };
}

const input = $('Buscar pendiente activo').first().json;
const pendiente = input.pendiente;
const pendienteRowIndex = input.pendienteRowIndex;
const config = input.config;
const groupJid = input.groupJid;

if (decision.accion !== 'cargar') {
  return [{
    json: {
      accion: decision.accion,
      razon: decision.razon,
      pendienteRowIndex,
      config,
      groupJid
    }
  }];
}

// Construir la estructura que espera Preparar fila
const df = decision.datos_finales || {};
const tipo = df.tipo || pendiente.tipo;

const esRemito = tipo === 'remito_cta1' || tipo === 'remito_cta2';
const esNDC = tipo === 'ndc_cta1' || tipo === 'ndc_cta2';
const esTransferencia = tipo === 'pago_transferencia';
const esCheque = tipo === 'pago_cheque';
const esEcheq = tipo === 'pago_echeq';
const esPago = esTransferencia || esCheque || esEcheq;

let cuenta = df.cuenta || pendiente.cuenta;
if (!cuenta) {
  if (tipo === 'remito_cta1' || tipo === 'ndc_cta1' || esEcheq) cuenta = 1;
  else if (tipo === 'remito_cta2' || tipo === 'ndc_cta2' || esCheque) cuenta = 2;
}

const sheetName = df.sheet_name || pendiente.sheet_name;
const monto = df.monto != null ? df.monto : pendiente.monto;
const comprobante = df.numero_comprobante || pendiente.comprobante || '';
const fecha = df.fecha || pendiente.fecha || '';
const notaCorta = df.nota_corta != null ? df.nota_corta : (pendiente.nota || '');
const clienteDetectado = df.cliente_detectado || pendiente.cliente_detectado || '';

// Si después de todo seguimos sin sheetName o sin cuenta o sin monto, ignoramos.
if (!sheetName || !cuenta || !monto) {
  return [{
    json: {
      accion: 'ignorar',
      razon: 'Datos insuficientes tras interpretar respuesta',
      pendienteRowIndex,
      config,
      groupJid
    }
  }];
}

return [{
  json: {
    accion: 'cargar',
    razon: decision.razon,
    extracted: {
      tipo,
      cliente_detectado: clienteDetectado,
      fecha,
      numero_comprobante: comprobante,
      nota_corta: notaCorta,
      monto,
      banco: pendiente.banco || '',
      dueno_cheque: pendiente.dueno_cheque || '',
      fecha_cobro: pendiente.fecha_cobro || ''
    },
    sheetName,
    cuenta,
    esRemito,
    esNDC,
    esTransferencia,
    esCheque,
    esEcheq,
    esPago,
    pendienteRowIndex,
    config,
    groupJid,
    messageId: pendiente.id
  }
}];
